import java.util.Locale;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Locale.setDefault(Locale.US);
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            return;
        }

        int n = sc.nextInt();
        double minPricePerKg = Double.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            double p = sc.nextDouble();
            int g = sc.nextInt();

            double pricePerKg = (p * 1000.0) / g;
            if (pricePerKg < minPricePerKg) {
                minPricePerKg = pricePerKg;
            }
        }

        System.out.printf(Locale.US, "%.2f\n", minPricePerKg);
        sc.close();
    }
}
